import Foundation

/// A prompt-only representation: time links are generated by the app, never inferred by an LLM.
/// The transcript editor and copy/export representations remain unchanged.
enum SummarySources {
    static func markdown(from segments: [TranscriptMarkdownBuilder.SegmentData]) throws -> String {
        var blocks: [String] = []
        for segment in segments {
            try Task.checkCancellation()
            let text = try EncryptionService.decryptForExternalAccess(segment.encryptedText)
            guard !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { continue }
            guard segment.startTime.isFinite, segment.startTime >= 0 else { throw LLMError.parseError }
            let speaker = segment.speaker.map { " · " + $0 } ?? ""
            blocks.append("[\(segment.timeRange)](Memozia://seek/\(segment.startTime))\(speaker)\n\(text)")
        }
        return blocks.joined(separator: "\n\n")
    }
}
